-- 1단계: 가장 하위에서 다른 테이블을 참조하기만 하는 실시간 통신 및 배송 데이터 소거
DROP TABLE IF EXISTS QNA_CHAT;
DROP TABLE IF EXISTS QNA_MAIL;
DROP TABLE IF EXISTS PURCHASE_DETAIL;

-- 2단계: 통신 허브 및 주문/장바구니 파트 소거
DROP TABLE IF EXISTS PARTICIPANT;
DROP TABLE IF EXISTS purchase;
DROP TABLE IF EXISTS basket;

-- 3단계: 상품 판매 및 입고 궤도 소거
DROP TABLE IF EXISTS PRODUCT_SALE;
DROP TABLE IF EXISTS STOCK_IN;

-- 4단계: 활동 등록부 및 도서 원천 데이터 소거
DROP TABLE IF EXISTS VENDOR_REGISTRATION;
DROP TABLE IF EXISTS USER_REGISTRATION;
DROP TABLE IF EXISTS BOOK;

-- 5단계: 최상위 마스터 원천 데이터 행성 최종 소거
DROP TABLE IF EXISTS VENDOR;
DROP TABLE IF EXISTS COSMIC_USER;
DROP TABLE IF EXISTS BASE_ADMIN;

-- 1. BASE_ADMIN: 사령부 관리자
CREATE TABLE BASE_ADMIN (
    admin_id VARCHAR(20) PRIMARY KEY,          
    admin_pw VARCHAR(100) NOT NULL,            
    admin_name VARCHAR(50) NOT NULL,           
    role VARCHAR(20) DEFAULT 'Admin',          
    regDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP 
);

-- 2. COSMIC_USER: 대원 원천 데이터 행성
CREATE TABLE COSMIC_USER (
    user_id VARCHAR(100) PRIMARY KEY,          
    user_pw VARCHAR(100),                      
    user_name VARCHAR(50) NOT NULL,            
    is_member INT DEFAULT 1,                   
    points INT DEFAULT 0,                      
    email VARCHAR(100),                        
    address VARCHAR(500) DEFAULT '銀河系 未指定 區域' NOT NULL,
    regDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP 
);

-- 3. USER_REGISTRATION: 유저 활동 등록부
CREATE TABLE USER_REGISTRATION (
    user_reg_num INT AUTO_INCREMENT PRIMARY KEY, 
    user_id VARCHAR(100) NOT NULL,             
    reg_status VARCHAR(20) DEFAULT 'ACTIVE',   
    regDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 
    FOREIGN KEY (user_id) REFERENCES COSMIC_USER(user_id)
);

-- 4. VENDOR: 업체 원천 데이터 행성
CREATE TABLE VENDOR (
    vendor_id VARCHAR(20) PRIMARY KEY,          
    vendor_pw VARCHAR(100) NOT NULL,            
    biz_name VARCHAR(100) NOT NULL,            
    biz_no VARCHAR(20) UNIQUE,                 
    contact VARCHAR(20),                       
    regDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP 
);

-- 5. VENDOR_REGISTRATION: 업체 활동 등록부
CREATE TABLE VENDOR_REGISTRATION (
    vendor_reg_num INT AUTO_INCREMENT PRIMARY KEY, 
    vendor_id VARCHAR(20) NOT NULL,            
    admin_id VARCHAR(20),                      
    is_active INT DEFAULT 0,                   
    regDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 
    FOREIGN KEY (vendor_id) REFERENCES VENDOR(vendor_id),
    FOREIGN KEY (admin_id) REFERENCES BASE_ADMIN(admin_id)
);

-- 6. BOOK: 도서 원천 데이터
CREATE TABLE BOOK (
    id INT AUTO_INCREMENT PRIMARY KEY,         
    title VARCHAR(255) NOT NULL,               
    writer VARCHAR(100) NOT NULL,              
    publisher VARCHAR(100),                    
    pubDate DATE,                              
    genre VARCHAR(50),                         
    language VARCHAR(20) DEFAULT 'Korean',      
    isbn VARCHAR(50) UNIQUE,                   
    image VARCHAR(500)                         
);

-- 7. STOCK_IN: 업체별 도서 입고
CREATE TABLE STOCK_IN (
    stock_id INT AUTO_INCREMENT PRIMARY KEY,   
    v_reg_num INT NOT NULL,                    
    book_id INT NOT NULL,                      
    qty INT NOT NULL,                          
    cost INT NOT NULL,                         
    regDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 
    FOREIGN KEY (v_reg_num) REFERENCES VENDOR_REGISTRATION(vendor_reg_num),
    FOREIGN KEY (book_id) REFERENCES BOOK(id)
);

-- 8. PRODUCT_SALE: 실시간 판매 상품
CREATE TABLE PRODUCT_SALE (
    sale_id INT AUTO_INCREMENT PRIMARY KEY,    
    stock_id INT NOT NULL,                     
    v_reg_num INT NOT NULL,                    
    price INT NOT NULL,                        
    stock_qty INT DEFAULT 0,                    
    sale_status VARCHAR(10) DEFAULT 'ON',      
    regDate TIMESTAMP DEFAULT CURRENT_TIMESTAMP, 
    FOREIGN KEY (stock_id) REFERENCES STOCK_IN(stock_id),
    FOREIGN KEY (v_reg_num) REFERENCES VENDOR_REGISTRATION(vendor_reg_num)
);

-- 9. BASKET: 장바구니 (🪐 중괄호 오타 정정 완료 및 세미콜론 추가)
CREATE TABLE basket (
    basket_id INT AUTO_INCREMENT PRIMARY KEY,
    user_reg_num INT NOT NULL,                  -- 활동 기준 번호 (FK)
    book_id INT NOT NULL,                       -- 도서 고유 ID (FK)
    sale_id INT DEFAULT NULL,                   -- 오픈마켓 상품 일련번호 (도서관 대여일 땐 NULL)
    qty INT DEFAULT 1 NOT NULL,                 -- 담은 수량 (자바의 b.qty와 100% 싱크 매핑)
    reg_date TIMESTAMP DEFAULT NOW() NOT NULL,   -- 등록 일시
    
    -- 외래키(FK) 안전핀 설정
    FOREIGN KEY (user_reg_num) REFERENCES USER_REGISTRATION(user_reg_num) ON DELETE CASCADE,
    FOREIGN KEY (book_id) REFERENCES BOOK(id) ON DELETE CASCADE,
    FOREIGN KEY (sale_id) REFERENCES PRODUCT_SALE(sale_id) ON DELETE CASCADE
);

-- 10. PURCHASE: 주문 마스터
CREATE TABLE purchase (
    purchase_id INT AUTO_INCREMENT PRIMARY KEY,
    user_reg_num INT NOT NULL,                  
    book_id INT NOT NULL,                       
    quantity INT NOT NULL,                      
    price INT DEFAULT 0 NOT NULL,               
    total_price INT DEFAULT 0 NOT NULL,         
    status VARCHAR(50) DEFAULT 'ORDERED' NOT NULL, 
    purchase_date TIMESTAMP DEFAULT NOW() NOT NULL, 
    FOREIGN KEY (user_reg_num) REFERENCES USER_REGISTRATION(user_reg_num) ON DELETE CASCADE,
    FOREIGN KEY (book_id) REFERENCES book(id) ON DELETE CASCADE
);

-- 11. PURCHASE_DETAIL: 품목별 배송 관제
CREATE TABLE PURCHASE_DETAIL (
    detail_id INT AUTO_INCREMENT PRIMARY KEY,  
    purchase_id INT NOT NULL,                  
    sale_id INT NOT NULL,                      
    v_reg_num INT NOT NULL,                    
    quantity INT NOT NULL,                     
    unit_price INT NOT NULL,                    
    tracking_no VARCHAR(50),                    
    delivery_status VARCHAR(20) DEFAULT 'READY', 
    FOREIGN KEY (purchase_id) REFERENCES PURCHASE(purchase_id),
    FOREIGN KEY (sale_id) REFERENCES PRODUCT_SALE(sale_id),
    FOREIGN KEY (v_reg_num) REFERENCES VENDOR_REGISTRATION(vendor_reg_num)
);

-- 12. PARTICIPANT: 통신 허브 테이블
CREATE TABLE PARTICIPANT (
    p_id INT AUTO_INCREMENT PRIMARY KEY,       
    p_type VARCHAR(10) NOT NULL,               
    u_reg_num INT UNIQUE,                      
    v_reg_num INT UNIQUE,                      
    admin_id VARCHAR(20) UNIQUE,               
    FOREIGN KEY (u_reg_num) REFERENCES USER_REGISTRATION(user_reg_num),
    FOREIGN KEY (v_reg_num) REFERENCES VENDOR_REGISTRATION(vendor_reg_num),
    FOREIGN KEY (admin_id) REFERENCES BASE_ADMIN(admin_id)
);

-- 13. QNA_MAIL: 비대면 문의 게시판
CREATE TABLE QNA_MAIL (
    mail_id INT AUTO_INCREMENT PRIMARY KEY,
    sender_pid INT NOT NULL,                   
    receiver_pid INT NOT NULL,                 
    title VARCHAR(255) NOT NULL,
    detail TEXT,                               
    answer TEXT,                               
    reg_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (sender_pid) REFERENCES PARTICIPANT(p_id),
    FOREIGN KEY (receiver_pid) REFERENCES PARTICIPANT(p_id)
);

-- 14. QNA_CHAT: 실시간 채팅 기록
CREATE TABLE QNA_CHAT (
    chat_id INT AUTO_INCREMENT PRIMARY KEY,
    sender_pid INT NOT NULL,                   
    receiver_pid INT NOT NULL,                 
    message TEXT NOT NULL,                     
    is_read INT DEFAULT 0,                     
    send_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (sender_pid) REFERENCES PARTICIPANT(p_id),
    FOREIGN KEY (receiver_pid) REFERENCES PARTICIPANT(p_id)
);




